#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    vector<int> a(n);
    for (auto &x : a) scanf("%d", &x);
    if (n == 1) {
        printf("0\n");
        return 0;
    }
    int m = 2 * n;
    vector<int> b(m);
    for (int i = 0; i < m; i++) b[i] = a[i % n];   // 倍長
    vector<int> pre(m + 1, 0);                      // 前綴和
    for (int i = 0; i < m; i++) pre[i + 1] = pre[i] + b[i];
    vector<vector<int>> dp(m, vector<int>(m, 0));
    for (int len = 2; len <= n; len++) {
        for (int i = 0; i + len - 1 < m; i++) {
            int j = i + len - 1;
            int best = INT_MAX;
            for (int k = i; k < j; k++)             // 最後一次合併的切點
                best = min(best, dp[i][k] + dp[k + 1][j]);
            dp[i][j] = best + pre[j + 1] - pre[i];
        }
    }
    int ans = INT_MAX;
    for (int s = 0; s < n; s++) ans = min(ans, dp[s][s + n - 1]);
    printf("%d\n", ans);
    return 0;
}

