using namespace std;

int par[2005], sz[2005];

int find(int x) {
    while (par[x] != x) {
        par[x] = par[par[x]];
        x = par[x];
    }
    return x;
}

int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    for (int i = 1; i <= n; i++) {
        par[i] = i;
        sz[i] = 1;
    }
    while (q--) {
        int t;
        scanf("%d", &t);
        if (t == 1) {
            int a, b;
            scanf("%d %d", &a, &b);
            int ra = find(a), rb = find(b);
            if (ra != rb) {
                if (sz[ra] < sz[rb]) swap(ra, rb);   // 小群掛大群
                par[rb] = ra;
                sz[ra] += sz[rb];
            }
        } else if (t == 2) {
            int a, b;
            scanf("%d %d", &a, &b);
            printf("%d\n", find(a) == find(b) ? 1 : 0);
        } else {
            int a;
            scanf("%d", &a);
            printf("%d\n", sz[find(a)]);
        }
    }
    return 0;
}

