// 回傳離 start 最遠的節點，並把距離寫入 dist
int farthest(int start, vector<int> &dist) {
    dist.assign(n + 1, -1);
    dist[start] = 0;
    vector<int> st = {start};
    while (!st.empty()) {
        int u = st.back();
        st.pop_back();
        for (auto [v, w] : adj[u]) {
            if (dist[v] < 0) {
                dist[v] = dist[u] + w;
                st.push_back(v);
            }
        }
    }
    int best = start;
    for (int i = 1; i <= n; i++)
        if (dist[i] > dist[best]) best = i;
    return best;
}

