#include <bits/stdc++.h>
using namespace std;

int n, m, timer_ = 0, bridges = 0;
vector<int> adj[1005];
int tin[1005], low_[1005];

void dfs(int u, int p) {
    tin[u] = low_[u] = ++timer_;
    for (int v : adj[u]) {
        if (v == p) continue;
        if (tin[v]) {
            low_[u] = min(low_[u], tin[v]);
        } else {
            dfs(v, u);
            low_[u] = min(low_[u], low_[v]);
            if (low_[v] > tin[u]) bridges++;
        }
    }
}

