import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    adj = [[] for _ in range(n + 1)]
    for i in range(n - 1):
        a, b = int(data[1 + 2 * i]), int(data[2 + 2 * i])
        adj[a].append(b)
        adj[b].append(a)
    parent = [0] * (n + 1)
    order = [1]                         # BFS 順序：父一定排在子之前
    for u in order:
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)
    size = [1] * (n + 1)
    for u in reversed(order):           # 由葉往根累加子樹大小
        if parent[u]:
            size[parent[u]] += size[u]
    best_v, best_f = 0, n + 1
    for u in range(1, n + 1):
        f = n - size[u]                 # 往上的那一塊
        for v in adj[u]:
            if v != parent[u]:
                f = max(f, size[v])     # 各子樹
        if f < best_f:                  # 編號由小到大掃，嚴格小於才更新 => 同分取最小編號
            best_v, best_f = u, f
    print(best_v, best_f)


