#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    vector<int> parent(n + 1, 0), order = {1}, sz(n + 1, 1);
    for (size_t i = 0; i < order.size(); i++) {
        int u = order[i];
        for (int v : adj[u])
            if (v != parent[u]) {
                parent[v] = u;
                order.push_back(v);
            }
    }
    for (int i = n - 1; i >= 1; i--) sz[parent[order[i]]] += sz[order[i]];
    int bestV = 0, bestF = n + 1;
    for (int u = 1; u <= n; u++) {
        int f = n - sz[u];
        for (int v : adj[u])
            if (v != parent[u]) f = max(f, sz[v]);
        if (f < bestF) {
            bestF = f;
            bestV = u;
        }
    }
    cout << bestV << ' ' << bestF << '\n';
    return 0;
}

