import sys

sys.setrecursionlimit(10000)


def main():
    data = sys.stdin.read().split()
    L, R, m = int(data[0]), int(data[1]), int(data[2])
    adj = [[] for _ in range(L + 1)]
    for i in range(m):
        adj[int(data[3 + 2 * i])].append(int(data[4 + 2 * i]))
    match_job = [0] * (R + 1)           # match_job[j] = 負責工作 j 的員工，0 表示空

    def try_assign(u, seen):
        """嘗試為員工 u 找到工作，必要時請佔著工作的員工改做別的（增廣路）。"""
        for j in adj[u]:
            if seen[j]:
                continue
            seen[j] = True
            if match_job[j] == 0 or try_assign(match_job[j], seen):
                match_job[j] = u
                return True
        return False

    result = 0
    for u in range(1, L + 1):
        if try_assign(u, [False] * (R + 1)):
            result += 1
    print(result)


main()

