#include <bits/stdc++.h>
using namespace std;

int n, m;
vector<vector<int>> g, rg;
vector<int> order_, comp;
vector<bool> seen;

void dfs1(int v) {
    seen[v] = true;
    for (int u : g[v])
        if (!seen[u]) dfs1(u);
    order_.push_back(v);
}

void dfs2(int v, int c) {
    comp[v] = c;
    for (int u : rg[v])
        if (comp[u] == -1) dfs2(u, c);
}

int main() {
    scanf("%d %d", &n, &m);
    g.assign(n + 1, {});
    rg.assign(n + 1, {});
    for (int i = 0; i < m; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        g[a].push_back(b);
        rg[b].push_back(a);
    }
    seen.assign(n + 1, false);
    comp.assign(n + 1, -1);
    for (int v = 1; v <= n; v++)
        if (!seen[v]) dfs1(v);
    int c = 0;
    for (int i = (int)order_.size() - 1; i >= 0; i--)
        if (comp[order_[i]] == -1) dfs2(order_[i], c++);
    if (c == 1) {
        printf("0\n");
        return 0;
    }
    vector<int> indeg(c, 0), outdeg(c, 0);
    for (int a = 1; a <= n; a++)
        for (int b : g[a])
            if (comp[a] != comp[b]) {
                outdeg[comp[a]]++;
                indeg[comp[b]]++;
