int n, m, timer_ = 0;
vector<vector<pair<int, int>>> adj;
vector<int> tin, low;
vector<bool> isBridge;

void dfs(int v, int pe) {
    tin[v] = low[v] = ++timer_;
    for (auto [u, e] : adj[v]) {
        if (e == pe) continue;
        if (tin[u]) {
            low[v] = min(low[v], tin[u]);
        } else {
            dfs(u, e);
            low[v] = min(low[v], low[u]);
            if (low[u] > tin[v]) isBridge[e] = true;
        }
    }
}

int main() {
    scanf("%d %d", &n, &m);
    adj.assign(n + 1, {});
    for (int i = 0; i < m; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        adj[a].push_back({b, i});
        adj[b].push_back({a, i});
    }
    tin.assign(n + 1, 0);
    low.assign(n + 1, 0);
    isBridge.assign(m, false);
    dfs(1, -1);
    int bridges = 0;
    for (int i = 0; i < m; i++) bridges += isBridge[i];
    if (bridges == 0) {
        printf("0\n");
        return 0;
    }
    vector<int> comp(n + 1, -1);
    int c = 0;
    for (int s = 1; s <= n; s++) {
        if (comp[s] >= 0) continue;
        comp[s] = c;
        vector<int> st = {s};
        while (!st.empty()) {
            int x = st.back();
            st.pop_back();
            for (auto [y, e] : adj[x])
                if (!isBridge[e] && comp[y] < 0) {
                    comp[y] = c;
                    st.push_back(y);
                }
        }
        c++;
    }
    vector<vector<int>> tree(c);
    for (int v = 1; v <= n; v++)
        for (auto [u, e] : adj[v])
            if (isBridge[e]) tree[comp[v]].push_back(comp[u]);
    auto bfs = [&](int src) {
        vector<int> d(c, -1);
        queue<int> q;
        d[src] = 0;
        q.push(src);
        while (!q.empty()) {
            int x = q.front();
            q.pop();
            for (int y : tree[x])
                if (d[y] < 0) {
                    d[y] = d[x] + 1;
                    q.push(y);
                }
        }
        return d;
    };
    vector<int> d0 = bfs(0);
    int far = max_element(d0.begin(), d0.end()) - d0.begin();
    vector<int> d1 = bfs(far);
    int diameter = *max_element(d1.begin(), d1.end());
    printf("%d\n", bridges - diameter);
    return 0;
}

