        int x, y;
        scanf("%d %d", &x, &y);
        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    vector<int> parent(n + 1, 0), order;
    vector<bool> seen(n + 1, false);
    queue<int> q;
    q.push(1);
    seen[1] = true;
    while (!q.empty()) {
        int x = q.front();
        q.pop();
        order.push_back(x);
        for (int y : adj[x])
            if (!seen[y]) {
                seen[y] = true;
                parent[y] = x;
                q.push(y);
            }
    }
    vector<long long> a(n + 1, 0), b(n + 1, 0), c(n + 1, 0);
    for (int i = n - 1; i >= 0; i--) {
        int v = order[i];
        a[v] = 1;
        long long sumB = 0, base = 0, bestGap = LLONG_MAX;
        bool anyKid = false, anyA = false;
        for (int u : adj[v]) {
            if (u == parent[v]) continue;
            anyKid = true;
            a[v] += min({a[u], b[u], c[u]});
            sumB += b[u];
            base += min(a[u], b[u]);
            if (a[u] <= b[u]) anyA = true;
            bestGap = min(bestGap, a[u] - b[u]);
        }
        c[v] = min<long long>(INF, sumB);
        if (!anyKid) b[v] = INF;
        else b[v] = min<long long>(INF, anyA ? base : base + bestGap);
    }
    printf("%lld\n", min(a[1], b[1]));
