int main() {
    int n, m, K;
    scanf("%d %d %d", &n, &m, &K);
    vector<vector<pair<int, int>>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int a, b, w;
        scanf("%d %d %d", &a, &b, &w);
        adj[a].push_back({b, w});
        adj[b].push_back({a, w});
    }
    int layers = K + 1;
    const long long INF = LLONG_MAX / 4;
    vector<long long> dist((n + 1) * layers, INF);
    typedef tuple<long long, int, int> T;
    priority_queue<T, vector<T>, greater<T>> pq;
    dist[1 * layers + 0] = 0;
    pq.push({0, 1, 0});
    while (!pq.empty()) {
        auto [d, v, k] = pq.top();
        pq.pop();
        if (d > dist[v * layers + k]) continue;
        for (auto [u, w] : adj[v]) {
            if (d + w < dist[u * layers + k]) {
                dist[u * layers + k] = d + w;
                pq.push({d + w, u, k});
            }
            if (k < K && d < dist[u * layers + k + 1]) {
                dist[u * layers + k + 1] = d;
                pq.push({d, u, k + 1});
            }
        }
    }
    long long ans = INF;
    for (int k = 0; k < layers; k++) ans = min(ans, dist[n * layers + k]);
    printf("%lld\n", ans);
    return 0;
}

