using namespace std;
using ll = long long;
const ll MOD = 1000000007LL;
string s;
size_t pos = 0;
ll expr();
ll factor() {
    if (s[pos] == '(') {
        pos++;
        ll v = expr();
        pos++;  // 跳過 ')'
        return v;
    }
    ll v = 0;
    while (pos < s.size() && isdigit((unsigned char)s[pos])) {
        v = (v * 10 + (s[pos] - '0')) % MOD;
        pos++;
    }
    return v;
}
ll term() {
    ll v = factor();
    while (pos < s.size() && s[pos] == '*') {
        pos++;
        v = v * factor() % MOD;
    }
    return v;
}
ll expr() {
    ll v = term();
    while (pos < s.size() && (s[pos] == '+' || s[pos] == '-')) {
        char op = s[pos++];
        ll w = term();
        v = (op == '+') ? (v + w) % MOD : ((v - w) % MOD + MOD) % MOD;
    }
    return v;
}
