// 最短重複單元：使 s 恰為該單元重複若干次
string primitiveRoot(const string &s) {
    int n = s.size();
    for (int p = 1; p <= n; p++) {
        if (n % p != 0) continue;
        bool ok = true;
        for (int i = p; i < n && ok; i++)
            if (s[i] != s[i - p]) ok = false;
        if (ok) return s.substr(0, p);
    }
    return s;
}

int main() {
    int n;
    cin >> n;
    map<string, long long> cnt;
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        cnt[primitiveRoot(s)]++;
    }
    long long ans = 0;
    for (auto &kv : cnt) ans += kv.second * (kv.second - 1) / 2;
    cout << ans << '\n';
    return 0;
}

