    for (int i = 0; i < (int)s.size(); i++) {
        char c = s[i];
        if (inStack[c - 'a']) continue;
        // 頂端比 c 大，且它之後還會再出現，就先彈出
        while (!st.empty() && st.back() > c && last[st.back() - 'a'] > i) {
            inStack[st.back() - 'a'] = false;
            st.pop_back();
        }
        st += c;
        inStack[c - 'a'] = true;
    }
    cout << st << '\n';
    return 0;
}

