import sys
from collections import deque

MOD = 10**9 + 7


def main():
    data = sys.stdin.read().split()
    n, k, m = int(data[0]), int(data[1]), int(data[2])
    words = data[3:3 + m]
    # 建 Aho-Corasick 自動機
    nxt = [[-1] * k]
    bad = [False]
    for w in words:
        u = 0
        for ch in w:
            c = ord(ch) - 97
            if nxt[u][c] == -1:
                nxt[u][c] = len(nxt)
                nxt.append([-1] * k)
                bad.append(False)
            u = nxt[u][c]
        bad[u] = True
    fail = [0] * len(nxt)
    q = deque()
    for c in range(k):
        v = nxt[0][c]
        if v == -1:
            nxt[0][c] = 0
        else:
            q.append(v)
    while q:
        u = q.popleft()
        bad[u] = bad[u] or bad[fail[u]]     # 後綴是禁語也算禁止
        for c in range(k):
            v = nxt[u][c]
            if v == -1:
                nxt[u][c] = nxt[fail[u]][c]
            else:
                fail[v] = nxt[fail[u]][c]
                q.append(v)
    S = len(nxt)
    dp = [0] * S
    dp[0] = 1
    for _ in range(n):
        nd = [0] * S
        for u in range(S):
            if dp[u] == 0:
                continue
            for c in range(k):
                v = nxt[u][c]
                if not bad[v]:
                    nd[v] = (nd[v] + dp[u]) % MOD
        dp = nd
    print(sum(dp) % MOD)


main()

