#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int main() {
    int n, k, m;
    cin >> n >> k >> m;
    vector<array<int, 26>> nxt(1);
    nxt[0].fill(-1);
    vector<char> bad(1, 0);
    for (int t = 0; t < m; t++) {
        string w;
        cin >> w;
        int u = 0;
        for (char ch : w) {
            int c = ch - 'a';
            if (nxt[u][c] == -1) {
                nxt[u][c] = nxt.size();
                array<int, 26> z;
                z.fill(-1);
                nxt.push_back(z);
                bad.push_back(0);
            }
            u = nxt[u][c];
        }
        bad[u] = 1;
    }
    int S = nxt.size();
    vector<int> fail(S, 0);
    queue<int> q;
    for (int c = 0; c < k; c++) {
        int v = nxt[0][c];
        if (v == -1) nxt[0][c] = 0;
        else q.push(v);
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (bad[fail[u]]) bad[u] = 1;   // 後綴是禁語也算禁止
        for (int c = 0; c < k; c++) {
            int v = nxt[u][c];
            if (v == -1) nxt[u][c] = nxt[fail[u]][c];
            else {
                fail[v] = nxt[fail[u]][c];
                q.push(v);
            }
        }
    }
    vector<long long> dp(S, 0), nd(S);
    dp[0] = 1;
    for (int step = 0; step < n; step++) {
        fill(nd.begin(), nd.end(), 0);
        for (int u = 0; u < S; u++) {
            if (!dp[u]) continue;
            for (int c = 0; c < k; c++) {
                int v = nxt[u][c];
                if (!bad[v]) nd[v] = (nd[v] + dp[u]) % MOD;
            }
        }
        dp = nd;
    }
    long long ans = 0;
    for (int u = 0; u < S; u++) ans = (ans + dp[u]) % MOD;
    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    // f[i][j]：子字串 s[i..j] 的最短編碼長度
    vector<vector<int>> f(n, vector<int>(n, 0));
    for (int len = 1; len <= n; len++) {
        for (int i = 0; i + len <= n; i++) {
            int j = i + len - 1;
            if (len == 1) {
                f[i][j] = 1;
                continue;
            }
            int best = len;  // 不壓縮
            for (int mid = i; mid < j; mid++)  // 串接：切成兩段
                best = min(best, f[i][mid] + f[mid + 1][j]);
            for (int p = 1; p < len; p++) {    // 重複：單元長 p
                if (len % p != 0) continue;
                bool ok = true;
                for (int t = p; t < len && ok; t++)
                    if (s[i + t] != s[i + t - p]) ok = false;
                if (ok) {
                    int k = len / p;
                    best = min(best, (int)to_string(k).size() + 2 + f[i][i + p - 1]);
                }
            }
            f[i][j] = best;
        }
    }
    cout << f[0][n - 1] << '\n';
    return 0;
}

