import sys

sys.setrecursionlimit(10000)


def parse_regex(text):
    """遞迴下降解析。節點：(種類, 字元, 子節點列表)，回傳 (節點表, 根編號)。"""
    nodes = []
    pos = [0]

    def new(kind, ch="", kids=()):
        nodes.append((kind, ch, list(kids)))
        return len(nodes) - 1

    def parse_alt():
        branches = [parse_cat()]
        while pos[0] < len(text) and text[pos[0]] == "|":
            pos[0] += 1
            branches.append(parse_cat())
        return branches[0] if len(branches) == 1 else new("alt", "", branches)

    def parse_cat():
        items = []
        while pos[0] < len(text) and text[pos[0]] not in "|)":
            items.append(parse_atom())
        return new("cat", "", items)

    def parse_atom():
        if text[pos[0]] == "(":
            pos[0] += 1
            node = parse_alt()
            pos[0] += 1                      # 吃掉 ')'
        else:
            node = new("c", text[pos[0]])
            pos[0] += 1
        if pos[0] < len(text) and text[pos[0]] in "*+?":
            node = new({"*": "star", "+": "plus", "?": "opt"}[text[pos[0]]], "", [node])
            pos[0] += 1
        return node

    root = parse_alt()
    return nodes, root


def make_ends(nodes, s):
    """ends(u, i)：節點 u 從位置 i 開始能匹配到的結束位置集合（位元遮罩）。"""
    memo = {}

    def bits(mask):
        i = 0
        while mask:
            if mask & 1:
                yield i
            mask >>= 1
            i += 1

    def closure(kid, reach):
        stack = list(bits(reach))
        while stack:
            j = stack.pop()
            new = ends(kid, j) & ~reach
            reach |= new
            stack.extend(bits(new))
        return reach

    def ends(u, i):
        key = (u, i)
        if key in memo:
            return memo[key]
        kind, ch, kids = nodes[u]
        if kind == "c":
            res = (1 << (i + 1)) if i < len(s) and s[i] == ch else 0
        elif kind == "cat":
            mask = 1 << i
            for v in kids:
                nm = 0
                for j in bits(mask):
                    nm |= ends(v, j)
                mask = nm
            res = mask
        elif kind == "alt":
            res = 0
            for v in kids:
                res |= ends(v, i)
        elif kind == "opt":
            res = ends(kids[0], i) | (1 << i)
        elif kind == "star":
            res = closure(kids[0], 1 << i)
        else:  # plus
            res = closure(kids[0], ends(kids[0], i))
        memo[key] = res
        return res

    return ends


def main():
    data = sys.stdin.read().split()
    text, q = data[0], int(data[1])
    nodes, root = parse_regex(text)
    for s in data[2:2 + q]:
        ends = make_ends(nodes, s)
        print("YES" if (ends(root, 0) >> len(s)) & 1 else "NO")


main()

