#include <bits/stdc++.h>
using namespace std;

// 節點：kind 為 'c' 字母、'k' 串接、'a' 選擇、'*' '+' '?' 後綴運算
struct Node {
    char kind, ch;
    vector<int> kids;
};
vector<Node> nodes;
string text;
size_t pos_;

int newNode(char kind, char ch, vector<int> kids) {
    nodes.push_back({kind, ch, kids});
    return nodes.size() - 1;
}

int parseAlt();

int parseAtom() {
    int node;
    if (text[pos_] == '(') {
        pos_++;
        node = parseAlt();
        pos_++;  // 吃掉 ')'
    } else {
        node = newNode('c', text[pos_], {});
        pos_++;
    }
    if (pos_ < text.size() && (text[pos_] == '*' || text[pos_] == '+' || text[pos_] == '?')) {
        node = newNode(text[pos_], 0, {node});
        pos_++;
    }
    return node;
}

int parseCat() {
    vector<int> items;
    while (pos_ < text.size() && text[pos_] != '|' && text[pos_] != ')')
        items.push_back(parseAtom());
    return newNode('k', 0, items);
}

int parseAlt() {
    vector<int> branches{parseCat()};
    while (pos_ < text.size() && text[pos_] == '|') {
        pos_++;
        branches.push_back(parseCat());
    }
    return branches.size() == 1 ? branches[0] : newNode('a', 0, branches);
}

string s;
vector<array<int, 16>> memo;  // memo[u][i]：節點 u 自位置 i 起可到達的結束位置遮罩，-1 表示尚未算

int ends(int u, int i);

int closureOf(int kid, int reach) {
    vector<int> stack;
    for (int j = 0; j < 16; j++)
        if (reach >> j & 1) stack.push_back(j);
    while (!stack.empty()) {
        int j = stack.back();
        stack.pop_back();
        int nw = ends(kid, j) & ~reach;
        reach |= nw;
        for (int t = 0; t < 16; t++)
            if (nw >> t & 1) stack.push_back(t);
    }
    return reach;
}

int ends(int u, int i) {
    int &res = memo[u][i];
    if (res != -1) return res;
    const Node &nd = nodes[u];
    int r = 0;
    if (nd.kind == 'c') {
        r = (i < (int)s.size() && s[i] == nd.ch) ? (1 << (i + 1)) : 0;
    } else if (nd.kind == 'k') {
        int mask = 1 << i;
        for (int v : nd.kids) {
            int nm = 0;
            for (int j = 0; j < 16; j++)
                if (mask >> j & 1) nm |= ends(v, j);
            mask = nm;
        }
        r = mask;
    } else if (nd.kind == 'a') {
        for (int v : nd.kids) r |= ends(v, i);
    } else if (nd.kind == '?') {
        r = ends(nd.kids[0], i) | (1 << i);
    } else if (nd.kind == '*') {
        r = closureOf(nd.kids[0], 1 << i);
    } else {  // '+'
        r = closureOf(nd.kids[0], ends(nd.kids[0], i));
    }
    return res = r;
}

int main() {
    int q;
    cin >> text >> q;
    pos_ = 0;
    int root = parseAlt();
    while (q--) {
        cin >> s;
        memo.assign(nodes.size(), array<int, 16>());
        for (auto &a : memo) a.fill(-1);
        cout << (((ends(root, 0) >> s.size()) & 1) ? "YES" : "NO") << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
