int main() {
    string s;
    long long k;
    cin >> s >> k;
    int n = s.size();
    vector<int> sa(n);
    iota(sa.begin(), sa.end(), 0);
    sort(sa.begin(), sa.end(), [&](int a, int b) {
        return s.compare(a, string::npos, s, b, string::npos) < 0;
    });
    int prev = -1;
    for (int idx : sa) {
        int lcp = 0;  // 與前一個後綴的最長共同前綴
        if (prev != -1)
            while (idx + lcp < n && prev + lcp < n && s[idx + lcp] == s[prev + lcp]) lcp++;
        long long nw = (n - idx) - lcp;  // 這個後綴貢獻的新相異子字串數
        if (k <= nw) {
            cout << s.substr(idx, lcp + k) << '\n';
            return 0;
        }
        k -= nw;
        prev = idx;
    }
    return 0;
}
